// SPDX-License-Identifier: Apache-2.0
// hipblaslt seed for FlashInfer-Bench/004_gemm_n128_k2048.
//
// Exists to prove the hipBLASLt path end to end -- a .hip submission that
// links against -lhipblaslt, runs the library's own heuristic-selected GEMM
// on the harness's stream, and passes the AMD-derived tolerance. It is a path
// test; it is also, being a vendor library call, about as fast as the anchor.
//
// The layout argument is the only subtle part. The problem is
// C[M,N] = A[M,K] @ B[N,K]^T with ALL THREE row-major, and hipBLASLt is
// column-major. A row-major MxK buffer read column-major is a KxM buffer, so
// with Acm = KxM(ldA=K) and Bcm = KxN(ldB=K):
//
//     C^T (N x M, column-major) = Bcm^T * Acm      -> opA = T, opB = N
//
// and a column-major NxM result is exactly the row-major MxN buffer the
// harness wants. Getting this wrong does not fail to compile; it produces
// numbers, and the tolerance is what catches it.
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <c10/hip/HIPStream.h>
#include <hipblaslt/hipblaslt.h>

#include <stdexcept>
#include <string>

namespace {

#define CHECK_BLASLT(expr)                                                    \
  do {                                                                        \
    hipblasStatus_t _s = (expr);                                              \
    if (_s != HIPBLAS_STATUS_SUCCESS) {                                       \
      throw std::runtime_error(std::string("hipblaslt failed: " #expr " -> ") \
                               + std::to_string(static_cast<int>(_s)));       \
    }                                                                         \
  } while (0)

// One handle for the process. Creating a handle per call would dominate the
// measurement and tell us nothing about the library's GEMM.
hipblasLtHandle_t get_handle() {
  static hipblasLtHandle_t handle = [] {
    hipblasLtHandle_t h = nullptr;
    CHECK_BLASLT(hipblasLtCreate(&h));
    return h;
  }();
  return handle;
}

constexpr size_t kWorkspaceBytes = 32ull * 1024 * 1024;

}  // namespace

torch::Tensor run(const torch::Tensor& A, const torch::Tensor& B) {
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == torch::kHalf && B.scalar_type() == torch::kHalf,
              "fp16 only");
  TORCH_CHECK(A.size(1) == B.size(1), "K mismatch");

  auto a = A.contiguous();
  auto b = B.contiguous();
  const int64_t M = a.size(0), K = a.size(1), N = b.size(0);
  auto c = torch::empty({M, N}, a.options());

  // Workspace as a torch tensor so it comes from the caching allocator the
  // harness already accounts for, rather than a raw hipMalloc.
  static torch::Tensor workspace;
  if (!workspace.defined() || workspace.device() != a.device()) {
    workspace = torch::empty({static_cast<int64_t>(kWorkspaceBytes)},
                             a.options().dtype(torch::kUInt8));
  }

  hipblasLtHandle_t handle = get_handle();

  hipblasLtMatmulDesc_t desc = nullptr;
  hipblasLtMatrixLayout_t la = nullptr, lb = nullptr, lc = nullptr;
  hipblasLtMatmulPreference_t pref = nullptr;
  CHECK_BLASLT(hipblasLtMatmulDescCreate(&desc, HIPBLAS_COMPUTE_32F, HIP_R_32F));
  hipblasOperation_t op_t = HIPBLAS_OP_T, op_n = HIPBLAS_OP_N;
  CHECK_BLASLT(hipblasLtMatmulDescSetAttribute(
      desc, HIPBLASLT_MATMUL_DESC_TRANSA, &op_t, sizeof(op_t)));
  CHECK_BLASLT(hipblasLtMatmulDescSetAttribute(
      desc, HIPBLASLT_MATMUL_DESC_TRANSB, &op_n, sizeof(op_n)));

  // "A" of the multiply is the problem's B (K x N column-major), "B" is the
  // problem's A (K x M column-major), and D is C^T (N x M column-major).
  CHECK_BLASLT(hipblasLtMatrixLayoutCreate(&la, HIP_R_16F, K, N, K));
  CHECK_BLASLT(hipblasLtMatrixLayoutCreate(&lb, HIP_R_16F, K, M, K));
  CHECK_BLASLT(hipblasLtMatrixLayoutCreate(&lc, HIP_R_16F, N, M, N));

  CHECK_BLASLT(hipblasLtMatmulPreferenceCreate(&pref));
  size_t ws = kWorkspaceBytes;
  CHECK_BLASLT(hipblasLtMatmulPreferenceSetAttribute(
      pref, HIPBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &ws, sizeof(ws)));

  hipblasLtMatmulHeuristicResult_t heur[1];
  int returned = 0;
  CHECK_BLASLT(hipblasLtMatmulAlgoGetHeuristic(handle, desc, la, lb, lc, lc,
                                               pref, 1, heur, &returned));
  if (returned == 0) {
    hipblasLtMatmulPreferenceDestroy(pref);
    hipblasLtMatrixLayoutDestroy(la);
    hipblasLtMatrixLayoutDestroy(lb);
    hipblasLtMatrixLayoutDestroy(lc);
    hipblasLtMatmulDescDestroy(desc);
    throw std::runtime_error("hipblaslt returned no algorithm for this shape");
  }

  const float alpha = 1.0f, beta = 0.0f;
  hipblasStatus_t st = hipblasLtMatmul(
      handle, desc, &alpha, b.data_ptr(), la, a.data_ptr(), lb, &beta,
      c.data_ptr(), lc, c.data_ptr(), lc, &heur[0].algo,
      workspace.data_ptr(), kWorkspaceBytes,
      c10::hip::getCurrentHIPStream());

  hipblasLtMatmulPreferenceDestroy(pref);
  hipblasLtMatrixLayoutDestroy(la);
  hipblasLtMatrixLayoutDestroy(lb);
  hipblasLtMatrixLayoutDestroy(lc);
  hipblasLtMatmulDescDestroy(desc);
  CHECK_BLASLT(st);

  return c;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("run", &run, "GEMM n128 k2048 fp16 via hipBLASLt (hipblaslt seed)");
}
